#!/usr/bin/env node
/**
 * Generate web, desktop, and Open Graph assets from static/brand/.
 * Keep the supplied paths and colors in the canonical SVG files.
 *
 * Requirements: Node 22+, the locked npm dependencies, and Playwright Chromium.
 * Install the browser once with: npx playwright install chromium
 * No app build, server, source archive, or extra package is required.
 *
 * Generate: node scripts/generate-brand-assets.mjs
 * Check:    node scripts/generate-brand-assets.mjs --check
 *
 * The check compares generated bytes on the current platform. Open Graph text
 * uses local system fonts. Use the same fonts and browser for identical PNGs.
 */
import { chromium } from '@playwright/test';
import { spawnSync } from 'node:child_process';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const GRAPHITE = '#0b0c0d';
const DESKTOP_PNG_SIZES = {
	'32x32.png': 32,
	'64x64.png': 64,
	'128x128.png': 128,
	'128x128@2x.png': 256,
	'icon.png': 512,
	'Square30x30Logo.png': 30,
	'Square44x44Logo.png': 44,
	'Square71x71Logo.png': 71,
	'Square89x89Logo.png': 89,
	'Square107x107Logo.png': 107,
	'Square142x142Logo.png': 142,
	'Square150x150Logo.png': 150,
	'Square284x284Logo.png': 284,
	'Square310x310Logo.png': 310,
	'StoreLogo.png': 50
};

/**
 * @param {Buffer} data
 * @param {number} width
 * @param {number} height
 * @param {string} label
 */
function checkPng(data, width, height, label) {
	const signature = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
	if (
		data.length < 24 ||
		!data.subarray(0, 8).equals(signature) ||
		data.readUInt32BE(16) !== width ||
		data.readUInt32BE(20) !== height
	) {
		throw new Error(`${label}: expected a ${width}x${height} PNG`);
	}
}

/**
 * Render vectors at the target size. The browser does not open the app.
 * @param {import('@playwright/test').Page} page
 * @param {string} svg
 * @param {number} width
 * @param {number} height
 * @param {{ opaque?: boolean, safeCircle?: boolean }} [options]
 */
async function renderPng(page, svg, width, height, { opaque = false, safeCircle = false } = {}) {
	const source = svg.replace(/<svg\b[^>]*>/, (tag) =>
		tag
			.replace(/\bwidth="[^"]*"/, `width="${width}"`)
			.replace(/\bheight="[^"]*"/, `height="${height}"`)
	);
	const dataUrl = await page.evaluate(
		async ({ source, width, height, opaque, safeCircle, background }) => {
			const image = new Image();
			image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(source)}`;
			await image.decode();
			const canvas = document.createElement('canvas');
			canvas.width = width;
			canvas.height = height;
			const context = canvas.getContext('2d');
			if (!context) throw new Error('Canvas 2D is not available');
			if (opaque) {
				context.fillStyle = background;
				context.fillRect(0, 0, width, height);
			}
			context.drawImage(image, 0, 0, width, height);
			if (opaque || safeCircle) {
				const pixels = context.getImageData(0, 0, width, height).data;
				const radius = Math.min(width, height) * 0.4;
				for (let y = 0; y < height; y += 1) {
					for (let x = 0; x < width; x += 1) {
						const index = (y * width + x) * 4;
						if (pixels[index + 3] !== 255) throw new Error('The icon must be fully opaque');
						const foreground =
							pixels[index] !== 11 || pixels[index + 1] !== 12 || pixels[index + 2] !== 13;
						if (
							safeCircle &&
							foreground &&
							Math.hypot(x + 0.5 - width / 2, y + 0.5 - height / 2) > radius
						) {
							throw new Error('The symbol exceeds the maskable safe circle');
						}
					}
				}
			}
			return canvas.toDataURL('image/png');
		},
		{ source, width, height, opaque, safeCircle, background: GRAPHITE }
	);
	const png = Buffer.from(dataUrl.slice(dataUrl.indexOf(',') + 1), 'base64');
	checkPng(png, width, height, 'Rendered asset');
	return png;
}

/**
 * Store PNG images in a standard multi-size ICO container.
 * @param {{ size: number, png: Buffer }[]} images
 */
function createIco(images) {
	const header = Buffer.alloc(6 + images.length * 16);
	header.writeUInt16LE(1, 2);
	header.writeUInt16LE(images.length, 4);
	let offset = header.length;
	for (const [index, { size, png }] of images.entries()) {
		const entry = 6 + index * 16;
		header.writeUInt8(size === 256 ? 0 : size, entry);
		header.writeUInt8(size === 256 ? 0 : size, entry + 1);
		header.writeUInt16LE(1, entry + 4);
		header.writeUInt16LE(32, entry + 6);
		header.writeUInt32LE(png.length, entry + 8);
		header.writeUInt32LE(offset, entry + 12);
		offset += png.length;
	}
	return Buffer.concat([header, ...images.map(({ png }) => png)]);
}

/**
 * Tauri can emit ICNS entries in a different order. Keep a stable order.
 * @param {Buffer} data
 */
function sortIcns(data) {
	if (
		data.length < 8 ||
		data.toString('ascii', 0, 4) !== 'icns' ||
		data.readUInt32BE(4) !== data.length
	) {
		throw new Error('Invalid ICNS container');
	}
	const entries = [];
	for (let offset = 8; offset < data.length;) {
		if (offset + 8 > data.length) throw new Error('Incomplete ICNS entry');
		const size = data.readUInt32BE(offset + 4);
		if (size < 8 || offset + size > data.length) throw new Error('Invalid ICNS entry size');
		entries.push(data.subarray(offset, offset + size));
		offset += size;
	}
	return Buffer.concat([data.subarray(0, 8), ...entries.sort(Buffer.compare)]);
}

/** @param {string} logo */
function createOgSvg(logo) {
	const embeddedLogo = logo
		.trim()
		.replace('width="356" height="104"', 'x="80" y="150" width="960" height="280.449438"');
	return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630" role="img" aria-labelledby="og-title og-desc">
  <title id="og-title">mdsh: offline Markdown editor</title>
  <desc id="og-desc">Your Markdown. On your device. No account. No server. No tracking.</desc>
  <rect width="1200" height="630" fill="#0b0c0d"/>
  <rect x="96" y="84" width="72" height="4" fill="#c79a55"/>
  <text x="192" y="93" font-family="Arial, Helvetica, sans-serif" font-size="16" letter-spacing="3" fill="#c79a55">OFFLINE MARKDOWN EDITOR</text>
${embeddedLogo}
  <text x="96" y="485" font-family="Arial, Helvetica, sans-serif" font-size="36" fill="#e6dfd1">Your Markdown. On your device.</text>
  <text x="96" y="556" font-family="Arial, Helvetica, sans-serif" font-size="22" fill="#bbb1a2">No account. No server. No tracking.</text>
</svg>
`;
}

/** @param {{ check?: boolean, ogOnly?: boolean }} [options] */
export async function generateBrandAssets({ check = false, ogOnly = false } = {}) {
	/** @type {Map<string, Buffer>} */
	const assets = new Map();
	const logo = await readFile(join(ROOT, 'static/brand/logo-dark.svg'), 'utf8');
	const ogSvg = createOgSvg(logo);
	assets.set('static/og-image.svg', Buffer.from(ogSvg));
	const browser = await chromium.launch();
	try {
		const page = await browser.newPage({ deviceScaleFactor: 1 });
		await page.route('**/*', (route) => route.abort());
		assets.set('static/og-image.png', await renderPng(page, ogSvg, 1200, 630, { opaque: true }));
		if (!ogOnly) {
			const icon = await readFile(join(ROOT, 'static/brand/app-icon.svg'), 'utf8');
			// The platform applies the mask to Apple and maskable icons.
			const squareIcon = icon.replace(/\brx="[^"]*"/, 'rx="0"');
			assets.set('static/favicon.svg', Buffer.from(icon));
			for (const size of [64, 192, 512]) {
				assets.set(`static/pwa-${size}x${size}.png`, await renderPng(page, icon, size, size));
			}
			assets.set(
				'static/maskable-icon-512x512.png',
				await renderPng(page, squareIcon, 512, 512, { opaque: true, safeCircle: true })
			);
			const appleIcon = await renderPng(page, squareIcon, 180, 180, { opaque: true });
			for (const name of [
				'apple-touch-icon.png',
				'apple-touch-icon-180x180.png',
				'apple-touch-icon-precomposed.png'
			]) {
				assets.set(`static/${name}`, appleIcon);
			}
			const faviconImages = [];
			for (const size of [16, 32, 48]) {
				faviconImages.push({ size, png: await renderPng(page, icon, size, size) });
			}
			assets.set('static/favicon.ico', createIco(faviconImages));
		}
	} finally {
		await browser.close();
	}

	if (!ogOnly) {
		const temporary = await mkdtemp(join(tmpdir(), 'mdsh-brand-assets-'));
		try {
			const require = createRequire(import.meta.url);
			const result = spawnSync(
				process.execPath,
				[
					require.resolve('@tauri-apps/cli/tauri.js'),
					'icon',
					join(ROOT, 'static/brand/app-icon.svg'),
					'--output',
					temporary,
					'--ios-color',
					GRAPHITE
				],
				{ cwd: ROOT, encoding: 'utf8' }
			);
			if (result.error) throw result.error;
			if (result.status !== 0) {
				throw new Error(`Tauri icon generation failed:\n${result.stderr || result.stdout}`);
			}
			for (const [name, size] of Object.entries(DESKTOP_PNG_SIZES)) {
				const png = await readFile(join(temporary, name));
				checkPng(png, size, size, name);
				assets.set(`src-tauri/icons/${name}`, png);
			}
			for (const name of ['icon.ico', 'icon.icns']) {
				const icon = await readFile(join(temporary, name));
				assets.set(`src-tauri/icons/${name}`, name === 'icon.icns' ? sortIcns(icon) : icon);
			}
		} finally {
			await rm(temporary, { recursive: true, force: true });
		}
	}

	const stale = [];
	for (const [path, content] of assets) {
		const target = join(ROOT, path);
		let current;
		try {
			current = await readFile(target);
		} catch (error) {
			if (!(error instanceof Error) || !('code' in error) || error.code !== 'ENOENT') throw error;
		}
		if (current?.equals(content)) continue;
		if (check) stale.push(path);
		else {
			await writeFile(target, content);
			console.log(`[brand] Wrote ${path} (${content.length} bytes)`);
		}
	}
	if (stale.length) throw new Error(`Brand assets need generation:\n${stale.join('\n')}`);
	console.log(`[brand] ${check ? 'Checked' : 'Generated'} ${assets.size} assets`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
	if (process.argv.slice(2).some((argument) => argument !== '--check')) {
		throw new Error('Usage: node scripts/generate-brand-assets.mjs [--check]');
	}
	await generateBrandAssets({ check: process.argv.includes('--check') });
}
